<?php if($viewData['database_error']):?><section class="empty-state"><h2>Review form unavailable</h2><p>Please try again later.</p></section><?php elseif($viewData['eligible_bookings']===[]):?><section class="empty-state"><h2>No booking is eligible</h2><p>Only completed Customer-owned bookings without an existing review can be reviewed.</p></section><?php else:?><form class="card feature-form" method="post" action="<?=htmlspecialchars(customer_url('reviews/create.php'),ENT_QUOTES,'UTF-8')?>" data-submit-once><?=CustomerCsrf::field()?><span class="demo-label demo-label--database">Database review</span><?php if(isset($viewData['errors']['form'])):?><div class="alert alert--error"><p><?=htmlspecialchars($viewData['errors']['form'],ENT_QUOTES,'UTF-8')?></p></div><?php endif;?><label for="review-booking">Completed booking</label><select id="review-booking" name="booking_id" required><option value="">Choose booking</option><?php foreach($viewData['eligible_bookings'] as $booking):?><option value="<?=(int)$booking['id']?>" <?= (string)$booking['id']===$viewData['form']['booking_id']?'selected':''?>>#<?=(int)$booking['id']?> — <?=htmlspecialchars($booking['make'].' '.$booking['model'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select><label for="vehicle-rating">Vehicle rating</label><select id="vehicle-rating" name="vehicle_rating" required><?php for($rating=5;$rating>=1;$rating--):?><option value="<?=$rating?>" <?=$viewData['form']['vehicle_rating']===(string)$rating?'selected':''?>><?=$rating?> / 5</option><?php endfor;?></select><label for="driver-rating">Driver rating <span class="form-hint">Optional; ignored for self-drive bookings</span></label><select id="driver-rating" name="driver_rating"><option value="">Not applicable</option><?php for($rating=5;$rating>=1;$rating--):?><option value="<?=$rating?>" <?=$viewData['form']['driver_rating']===(string)$rating?'selected':''?>><?=$rating?> / 5</option><?php endfor;?></select><label for="review-text">Review text <span class="form-hint">Plain text, maximum 1500 characters</span></label><textarea id="review-text" name="review_text" maxlength="1500" data-character-input><?=htmlspecialchars($viewData['form']['review_text'],ENT_QUOTES,'UTF-8')?></textarea><span class="form-hint" data-character-count>0 / 1500</span><button class="button button--primary" type="submit">Save Review</button></form><?php endif;?>
